int predict_mlp(const float *features)
{
    float x[NUM_FEATURES];
    for (int i = 0; i < NUM_FEATURES; i++) {
        x[i] = (features[i] - scaler_mean[i]) * scaler_inv_std[i];
    }

    float h1[8];
    for (int j = 0; j < 8; j++) {
        float sum = b1[j];
        for (int i = 0; i < NUM_FEATURES; i++) {
            sum += w1[j][i] * x[i];
        }
        h1[j] = sum > 0.0f ? sum : 0.0f;
    }

    float h2[8];
    for (int j = 0; j < 8; j++) {
        float sum = b2[j];
        for (int i = 0; i < 8; i++) {
            sum += w2[j][i] * h1[i];
        }
        h2[j] = sum > 0.0f ? sum : 0.0f;
    }

    int best = 0;
    float best_logit = b3[0];
    for (int i = 0; i < 8; i++) {
        best_logit += w3[0][i] * h2[i];
    }
    for (int c = 1; c < NUM_CLASSES; c++) {
        float logit = b3[c];
        for (int i = 0; i < 8; i++) {
            logit += w3[c][i] * h2[i];
        }
        if (logit > best_logit) {
            best_logit = logit;
            best = c;
        }
    }
    return best;
}
